  ('NOM127','NOM - 127 - SSA 1- 2021','Tiene como finalidad establecer los límites permisibles de calidad que debe cumplir el agua destinada al consumo humano, asegurando que los sistemas de abastecimiento públicos y privados entreguen agua segura y apta para consumo y es de observancia obligatoria en todo el territorio nacional.','ambiental','agua',4,3,1.0,false,1.0,0.9,'https://dof.gob.mx/nota_detalle_popup.php?codigo=5650705',(select id from jurisdicciones where clave='FED'),true),
